mapper.select:
SELECT a.* FROM ( SELECT *, DATE_FORMAT(create_time, '%Y-%m-%d') AS lastTime FROM t_iot_device_data WHERE point_id IN
#{pointId}
GROUP BY point_id,lastTime ORDER BY lastTime DESC ) a LEFT JOIN ( SELECT create_time, point_id, DATE_FORMAT(create_time, '%Y-%m-%d') AS lastTime FROM t_iot_device_data WHERE point_id IN
#{pointId}
GROUP BY point_id,lastTime ORDER BY lastTime DESC ) b ON a.point_id = b.point_id AND a.lastTime = DATE_ADD(b.lastTime, INTERVAL 1 DAY)
